import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingGpxToFront, mapHikingGpxWithWorkoutToFront } from '../@mappers/hikingGpx.mapper';
import { IHikingGpxDTO } from '../@types/DTO/hiking.dto.types';
import { IHikingGpx, IHikingGpxWithWorkout } from '../@types/hiking.types';

interface IGetHikingGPXCriteria {
  /** From date for filter */
  d1?: string;

  /** TO Date for filter */
  d2?: string;

  /** Contains date for find between start and end of track */
  d?: string;
}

export const getHikingGpx = async (
  id_hiking: number,
  criteria: IGetHikingGPXCriteria = {},
): Promise<IHikingGpx[]> => {
  const res = await get<IHikingGpxDTO[]>('/ajax/hiking/gpx/load.php', { id_hiking, ...criteria });
  return res.map(mapHikingGpxToFront);
};
export const getHikingGpxTrackById = async (
  id_hiking_track: number,
): Promise<IHikingGpxWithWorkout> => {
  const res = await get<IHikingGpxDTO>('/ajax/hiking/gpx/one.php', { id_hiking_track });
  return mapHikingGpxWithWorkoutToFront(res);
};

export const addHikingGpx = async (
  id_hiking: number,
  id_workout_track: number,
  name: string,
  id_hiking_schedule: null | number = null,
) => {
  return await post('/ajax/hiking/gpx/add.php', {
    id_hiking,
    id_workout_track,
    name,
    id_hiking_schedule,
  });
};

export const delHikingGpx = async (data: { id_hiking: number; id: number }) => {
  return await post('/ajax/hiking/gpx/del.php', data).then(handleApiError);
};
export const editHikingGpx = async (data: {
  id_hiking_track: number;
  name: string;
  id_hiking_schedule: number | null;
}) => {
  return await post('/ajax/hiking/gpx/edit.php', data).then(handleApiError);
};
